import {icon} from './icons.js';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const button=(text,action,cls='secondary',attrs='')=>`<button type="button" class="btn ${cls}" data-internal-action="${action}" ${attrs}>${text}</button>`;
const when=t=>new Intl.DateTimeFormat('es-DO',{dateStyle:'medium',timeStyle:'short',timeZone:'America/Santo_Domingo'}).format(new Date(t));
const statuses={pending:'Pendiente · 10 segundos para cancelar',published:'Publicada en la bandeja de tus contactos',canceled:'Cancelada · no publicada',expired:'Venció sin publicarse',failed:'No publicada · contactos ya no disponibles',queued:'En espera',available:'Disponible en su bandeja · lectura sin confirmar',read:'Lectura confirmada por el contacto',skipped:'No publicada · permiso retirado'};
const relationStatus={pending:'Pendiente de aceptación',accepted:'Aceptado',declined:'Rechazado o recepción desactivada',removed:'Eliminado'};
export function createInternalUI({onChange,notify}){
 let cloud=null,user=null,profile=null,data={links:[],events:[],inbox:[],outbox:[]},code='',ready=false,error='',pollError='',busy=false,polling=false,generation=0,offset=0,recovery=null,loaded=false;
 let dialog=document.createElement('dialog');dialog.id='internal-modal';dialog.setAttribute('aria-labelledby','internal-title');document.body.append(dialog);
 let lastFocus=null,tick=0;
 const changed=()=>{if(!document.activeElement?.matches('main input, main textarea, main select'))onChange();};
 const key=()=>`alerta-internal-request-${user?.id}`;
 function remember(id){recovery=id;try{id?localStorage.setItem(key(),id):localStorage.removeItem(key());}catch{}}
 const outgoing=()=>data.links.filter(l=>l.sender_id===user?.id&&l.status!=='removed');
 const incoming=()=>data.links.filter(l=>l.recipient_id===user?.id&&l.status!=='removed');
 const accepted=()=>outgoing().filter(l=>l.status==='accepted');
 const pending=()=>data.events.find(e=>e.status==='pending');
 const remaining=e=>Math.max(0,Math.ceil((Date.parse(e.send_after)-Date.now()-offset)/1000));
 function reset(){generation++;cloud=null;user=null;profile=null;code='';ready=false;error='';pollError='';loaded=false;recovery=null;data={links:[],events:[],inbox:[],outbox:[]};dialog.close();}
 async function attach(nextCloud,session,nextProfile){
   if(!session){reset();return;}if(!nextCloud?.internal)return;
   if(user?.id!==session.user.id){reset();cloud=nextCloud;user=session.user;try{recovery=localStorage.getItem(key());}catch{}}
   profile=nextProfile;
   if(!loaded)await refresh();
 }
 async function refresh(){
   if(!cloud||!user||polling)return;
   polling=true;const version=generation;
   try{
     const [next,health,identity]=await Promise.all([cloud.internalData(),cloud.internal({action:'health'}),code?Promise.resolve({code}):cloud.internal({action:'code'})]);
     if(version!==generation)return;
     const unseen=next.inbox.filter(i=>!data.inbox.some(old=>old.id===i.id));
     const before=JSON.stringify([data,ready,pollError,code]);data=next;ready=health.ready;code=identity.code;pollError='';
     if(Number.isFinite(health.serverTime))offset=health.serverTime-Date.now();
     if(recovery&&data.events.some(e=>e.request_id===recovery))remember(null);
     if(loaded&&unseen.length&&document.querySelector('[data-internal-root]'))notify('Recibiste una alerta en Alerta RD. Abre tu bandeja en Central / Historial.',true);
     loaded=true;
     if(before!==JSON.stringify([data,ready,pollError,code]))changed();
   }catch{if(version===generation){ready=false;pollError='No se pudo actualizar la bandeja. Comprueba la conexión y pulsa Actualizar. Los SOS ya registrados continúan en el servidor.';changed();}}
   finally{polling=false;}
 }
 const notice=()=>`${error?`<p class="form-error" role="alert">${esc(error)}</p>`:''}${pollError?`<p class="notice" role="status">${esc(pollError)}</p>`:''}`;
 function banner(){if(!cloud)return '';const count=data.inbox.filter(i=>!i.read_at).length,invites=incoming().filter(l=>l.status==='pending').length;return `<div class="internal-banner" data-internal-root><span>${icon('shield')} <strong>Alertas en Alerta RD</strong></span><div class="button-row"><button class="btn ${count?'danger':'ghost'}" data-page="history">Bandeja${count?` · ${count} sin leer`:''}</button>${invites?`<button class="btn secondary" data-page="contacts">${invites} solicitud${invites===1?'':'es'}</button>`:''}</div></div>`;}
 function sos(){const e=pending();return `<header class="page-heading"><div><p class="eyebrow">TU CÍRCULO · ALERTAS INTERNAS</p><h1 tabindex="-1">SOS en Alerta RD</h1><p class="subtitle">Avisa a tus amigos registrados desde aquí. Sin depender de WhatsApp.</p></div></header>${notice()}<div class="sos-layout"><section class="card sos-card"><div class="card-top"><span class="section-label">ALERTA EN LA CUENTA DE TUS AMIGOS</span><span class="badge red">ENVÍO INTERNO REAL</span></div>${e?`<div class="real-countdown"><span class="large-timer" data-internal-countdown>${remaining(e)}</span><h2>${statuses.pending}</h2><p>Al vencer el plazo, el servidor publicará la alerta en las cuentas vinculadas. Cerrar esta página no cancela el SOS.</p>${button('Estoy bien · Cancelar SOS','cancel','success full',`data-id="${e.id}" ${busy||remaining(e)===0?'disabled':''}`)}<p data-internal-wait>${remaining(e)===0?'Plazo finalizado · esperando publicación del servidor':''}</p></div>`:`<div class="sos-orbit"><button class="sos-button" data-internal-action="start" aria-label="Iniciar SOS interno con 10 segundos para cancelar" ${busy||recovery||!ready||!profile?.name||!accepted().length?'disabled':''}><span>SOS</span><small>AVISAR A MIS AMIGOS</small></button></div><h2>${ready&&accepted().length&&profile?.name?'Tu círculo está listo.':'Prepara tu círculo.'}</h2><p class="sos-description">${accepted().length?'Tendrás 10 segundos para cancelar. Se compartirá tu nombre, fecha y ubicación si está disponible.':'Agrega un amigo registrado y espera que acepte tu solicitud en Contactos.'}</p>`}<div class="sos-card-footer">${icon('info')} Alerta real dentro de Alerta RD. No avisa al 9-1-1.</div></section><div class="sos-right"><section class="card"><h2>Antes de activar</h2><dl class="facts"><div><dt>Tu nombre</dt><dd>${esc(profile?.name||'Completa Perfil')}</dd></div><div><dt>Amigos que aceptaron</dt><dd>${accepted().length} de 5</dd></div><div><dt>Procesador interno</dt><dd>${ready?'Disponible':'Sin confirmar'}</dd></div><div><dt>Canal</dt><dd>Bandeja de Alerta RD</dd></div></dl><div class="button-row"><button class="btn secondary" data-page="profile">Mi perfil</button><button class="btn primary" data-page="contacts">Mis amigos</button></div>${button('Actualizar estado','refresh','ghost full')}</section><section class="card"><h3>¿Cómo le llega?</h3><p>Con la web abierta y la sesión iniciada, la bandeja se actualiza cada 5 segundos. Si está cerrada, la alerta queda guardada para cuando entre.</p><p><strong>No hay notificaciones push con la página cerrada.</strong> Que esté en la bandeja no significa que tu amigo la haya visto.</p><p class="form-hint">Si deniegas la ubicación, la alerta se publica igualmente como «Ubicación no disponible».</p></section></div></div>${recovery?`<section class="card"><h2>Solicitud por confirmar</h2><p>No recibimos una respuesta definitiva. Recupera la misma solicitud para evitar duplicados.</p>${button('Recuperar la misma solicitud','recover','primary')}</section>`:''}${data.events[0]&&!e?`<section class="card"><h3>Último SOS interno</h3>${eventRow(data.events[0])}</section>`:''}`;}
 function contacts(){return `<section class="internal-contacts"><header class="page-heading"><div><p class="eyebrow">PERSONAS QUE TE ACOMPAÑAN</p><h1 tabindex="-1">Amigos en Alerta RD</h1><p class="subtitle">Vincula a una persona registrada para que reciba tus alertas aquí.</p></div></header>${notice()}<div class="two-columns"><section class="card"><h2>Tu código de contacto</h2><p>Tu amigo lo encontrará aquí en su propia cuenta. Pídeselo para agregarlo, o comparte el tuyo para recibir sus alertas.</p><label for="internal-code">Código de tu cuenta</label><input id="internal-code" value="${esc(code)}" readonly autocomplete="off">${button('Copiar mi código','copy','secondary full',!code?'disabled':'')}<p class="form-hint">Cada dirección requiere aceptación. Compartir tu código no comparte tu ubicación.</p></section><section class="card"><h2>Agrega a tu amigo</h2><p>Ambos deben completar su nombre en Perfil. Tu amigo aceptará la solicitud desde su cuenta.</p>${button('Agregar amigo registrado','invite','primary full',busy||outgoing().filter(l=>l.status!=='declined').length>=5?'disabled':'')}${button('Actualizar contactos','refresh','ghost full')}</section></div><h2 class="internal-section-title">Reciben mis alertas</h2><div class="contacts-grid">${outgoing().map(l=>`<section class="card"><h3>${esc(l.recipient_name)}</h3><p>${esc(l.relation)}</p><span class="badge ${l.status==='accepted'?'green':'amber'}">${relationStatus[l.status]}</span>${button('Eliminar de mis contactos','remove-prompt','ghost full',`data-id="${l.id}"`)}</section>`).join('')||'<section class="card empty"><h3>Tu primer amigo está a un código de distancia</h3><p>Agrega a alguien de confianza para preparar tu SOS interno.</p></section>'}</div><h2 class="internal-section-title">Solicitudes y alertas que acepto recibir</h2><div class="contacts-grid">${incoming().map(l=>`<section class="card"><h3>${esc(l.sender_name)}</h3><p>${esc(l.relation)} · ${relationStatus[l.status]}</p>${l.status==='pending'?`<p>Si aceptas, verás sus SOS y la ubicación que decida compartir. Podrás dejar de recibirlos.</p><div class="button-row">${button('Aceptar solicitud','accept','success',`data-id="${l.id}"`)}${button('Rechazar','reject','ghost',`data-id="${l.id}"`)}</div>`:l.status==='accepted'?button('Dejar de recibir sus alertas','remove-prompt','ghost',`data-id="${l.id}"`):''}</section>`).join('')||'<section class="card empty"><p>No tienes solicitudes. Comparte tu código con quien quieras que te agregue.</p></section>'}</div></section>`;}
 function eventRow(e){return `<button class="event-row" data-internal-action="event" data-id="${e.id}"><span class="icon-tile red">${icon('shield')}</span><span class="event-copy"><strong>SOS interno · ${statuses[e.status]}</strong><small>${when(e.created_at)}</small></span>${icon('chevron')}</button>`;}
 function history(){return `<section><header class="page-heading"><div><p class="eyebrow">TU BANDEJA PRIVADA</p><h1 tabindex="-1">Alertas en Alerta RD</h1><p class="subtitle">Recibidas y enviadas. Horario de República Dominicana.</p></div>${button('Actualizar bandeja','refresh')}</header>${notice()}<h2>Alertas recibidas</h2><p class="form-hint">Actualización automática cada 5 segundos con esta página visible. Últimas 100 alertas.</p><section class="card">${data.inbox.map(i=>`<button class="event-row" data-internal-action="inbox" data-id="${i.id}"><span class="icon-tile ${i.read_at?'green':'red'}">${icon('shield')}</span><span class="event-copy"><strong>${esc(i.sender_name)} activó un SOS</strong><small>${when(i.created_at)} · ${i.read_at?'Lectura confirmada':'Sin leer'}</small></span>${icon('chevron')}</button>`).join('')||'<div class="empty"><h3>No has recibido alertas</h3><p>Cuando una persona vinculada active SOS, la alerta aparecerá aquí después de su cuenta regresiva.</p></div>'}</section><h2 class="internal-section-title">Mis SOS internos</h2><section class="card">${data.events.map(eventRow).join('')||'<div class="empty"><p>Tus SOS y cancelaciones aparecerán aquí.</p></div>'}</section></section>`;}
 function open(title,body){lastFocus=document.activeElement;dialog.innerHTML=`<div class="modal-head"><h2 id="internal-title">${title}</h2>${button(icon('x'),'close','icon-button','aria-label="Cerrar"')}</div><div class="modal-body">${body}<p class="form-error" role="alert"></p></div>`;if(!dialog.open)dialog.showModal();}
 function close(){dialog.close();if(lastFocus?.isConnected)lastFocus.focus();}
 const place=i=>Number.isFinite(i.latitude)&&Number.isFinite(i.longitude)?`<a class="btn secondary" target="_blank" rel="noopener noreferrer" href="https://www.google.com/maps?q=${i.latitude},${i.longitude}">${icon('pin')} Ver ubicación compartida</a>`:'<p>Ubicación no disponible</p>';
 function showInbox(id){const i=data.inbox.find(i=>i.id===id);if(!i)return;open('Alerta recibida',`<span class="badge red">SOS INTERNO REAL</span><h3>${esc(i.sender_name)} necesita que lo contactes</h3><p>${when(i.created_at)}</p>${place(i)}<p>Contacta a esta persona por los medios que ya tengas. No te pongas en riesgo. Esta web no ha avisado al 9-1-1.</p>${i.read_at?`<p>Confirmaste la lectura el ${when(i.read_at)}.</p>`:button('Confirmar que vi esta alerta','read','primary full',`data-id="${i.id}"`)}<p class="form-hint">Confirmar lectura no equivale a que la emergencia esté resuelta.</p>`);}
 function showEvent(id){const e=data.events.find(e=>e.id===id);if(!e)return;open('Detalle del SOS interno',`<p>${when(e.created_at)}</p><h3>${statuses[e.status]}</h3>${place(e)}<div class="delivery-list">${data.outbox.filter(d=>d.event_id===id).map(d=>`<div class="delivery-result"><strong>${esc(d.recipient_name)}</strong><p>${statuses[d.status]}</p>${d.read_at?`<small>${when(d.read_at)}</small>`:''}</div>`).join('')}</div><p>«Disponible en su bandeja» confirma que se guardó en su cuenta. La lectura requiere confirmación de tu contacto.</p>`);}
 async function create(id){const version=generation;let result;
   try{result=await cloud.internal({action:'create',requestId:id});}catch(e){if(e.definitive)remember(null);throw e;}
   if(version!==generation)return;remember(null);offset=result.serverTime-Date.now();data.events=[result.event,...data.events.filter(e=>e.id!==result.event.id)];changed();
   if(result.event.status==='pending'){
     const eventId=result.event.id,currentCloud=cloud;
     if(!navigator.geolocation)notify('Ubicación no disponible. Tu SOS interno continúa.');
     navigator.geolocation?.getCurrentPosition(async pos=>{if(version!==generation)return;try{await currentCloud.internal({action:'location',eventId,latitude:pos.coords.latitude,longitude:pos.coords.longitude});notify('Ubicación añadida al SOS interno.');}catch{notify('No se añadió la ubicación. El SOS continúa igualmente.');}},()=>{if(version===generation)notify('Ubicación no disponible. El SOS interno continúa igualmente.');},{timeout:6000,maximumAge:0,enableHighAccuracy:true});
   }
   await refresh();
 }
 async function action(a,el){if(a==='close'){close();return;}if(!user||busy)return;error='';
   if(a==='invite'){open('Agregar amigo registrado',`<form id="internal-invite-form"><label for="friend-code">Código de contacto de tu amigo</label><input id="friend-code" name="code" required maxlength="36" placeholder="Pega aquí su código" autocomplete="off"><label for="friend-relation">Parentesco o relación</label><input id="friend-relation" name="relation" required maxlength="50" placeholder="Ej. Amigo, hermana…"><p>Se enviará una solicitud dentro de su cuenta. Recibirá tus SOS después de aceptarla.</p><p class="form-error" role="alert"></p><button class="btn primary" type="submit">Enviar solicitud</button></form>`);return;}
   if(a==='remove-prompt'){open('¿Retirar este vínculo?',`<p>Este vínculo dejará de recibir nuevos SOS. Las alertas que ya se publicaron permanecen en el historial.</p>${button('Confirmar','remove','danger',`data-id="${el.dataset.id}"`)}${button('Cancelar','close','ghost')}`);return;}
   if(a==='inbox'){showInbox(el.dataset.id);return;}if(a==='event'){showEvent(el.dataset.id);return;}
   busy=true;el.disabled=true;
   try{
     if(a==='refresh')await refresh();
     if(a==='copy'){try{await navigator.clipboard.writeText(code);notify('Código copiado. Compártelo con tu amigo.');}catch{document.querySelector('#internal-code')?.select();notify('Selecciona y copia el código con Ctrl+C.');}}
     if(a==='accept'||a==='reject'){await cloud.internal({action:'respond',id:el.dataset.id,accept:a==='accept'});await refresh();notify(a==='accept'?'Solicitud aceptada. Recibirás sus SOS en tu bandeja.':'Solicitud rechazada.');}
     if(a==='remove'){await cloud.internal({action:'remove',id:el.dataset.id});close();await refresh();notify('Vínculo retirado.');}
     if(a==='start'&&!pending()&&!recovery){const id=crypto.randomUUID();remember(id);await create(id);}
     if(a==='recover'&&recovery)await create(recovery);
     if(a==='cancel'){await cloud.internal({action:'cancel',eventId:el.dataset.id});await refresh();notify('SOS interno cancelado. No se publicó en las cuentas de tus amigos.');}
     if(a==='read'){await cloud.internal({action:'read',id:el.dataset.id});await refresh();showInbox(el.dataset.id);notify('Lectura confirmada.');}
   }catch(e){error=e.message||'No se pudo completar la operación.';if(dialog.open)dialog.querySelector('.form-error').textContent=error;notify(error,true);}
   finally{busy=false;if(el.isConnected)el.disabled=false;changed();}
 }
 document.addEventListener('click',e=>{const el=e.target.closest('[data-internal-action]');if(el&&!el.disabled){e.preventDefault();action(el.dataset.internalAction,el);}});
 document.addEventListener('submit',async e=>{if(e.target.id!=='internal-invite-form')return;e.preventDefault();if(busy||!cloud)return;const form=e.target,fields=Object.fromEntries(new FormData(form));
   if(!/^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(fields.code.trim())){form.querySelector('.form-error').textContent='Copia el código completo desde Contactos en la cuenta de tu amigo.';return;}
   busy=true;form.querySelector('button').disabled=true;
   try{await cloud.internal({action:'invite',code:fields.code.trim(),relation:fields.relation.trim()});close();await refresh();notify('Solicitud guardada en la cuenta de tu amigo. Falta que la acepte.');}catch(err){form.querySelector('.form-error').textContent=err.message;}
   finally{busy=false;form.querySelector('button').disabled=false;changed();}
 });
 setInterval(()=>{
   const e=pending(),timer=document.querySelector('[data-internal-countdown]');if(e&&timer){const n=remaining(e);timer.textContent=n;if(n===0){const b=document.querySelector('[data-internal-action="cancel"]');if(b)b.disabled=true;const hint=document.querySelector('[data-internal-wait]');if(hint)hint.textContent='Plazo finalizado · esperando publicación del servidor';}}
   if(++tick%5===0&&user&&!document.hidden&&!busy)refresh();
 },1000);
 document.addEventListener('visibilitychange',()=>{if(!document.hidden&&user)refresh();});
 return {attach,reset,refresh,banner,sos,contacts,history,enabled:()=>!!cloud,hasActive:()=>!!pending()||!!recovery};
}
